INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("", 1, 0, 24001, 35, 2, 30000, 0, "", 15, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("", 100, 0, 91002, 36, 8, 40000, 0, "", 1, 0);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("ぺコリーヌ", 150, 1, 91002, 37, 8, 40001, 0, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 1, 107501);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("コッコロ", 150, 1, 91002, 38, 8, 40001, 0, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 2, 107601);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("キャル", 150, 1, 91002, 39, 8, 40001, 0, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 3, 107801);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("スズメ", 150, 1, 91002, 40, 8, 40001, 0, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 4, 107701);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("タマキ", 150, 1, 91002, 41, 8, 40001, 0, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 5, 107901);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("ぺコリーヌ", 150, 2, 91002, 42, 8, 40001, 0, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 6, 107501);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("コッコロ", 150, 2, 91002, 43, 8, 40001, 0, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 7, 107601);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("キャル", 150, 2, 91002, 44, 8, 40001, 0, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 8, 107801);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("スズメ", 150, 2, 91002, 45, 8, 40001, 0, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 9, 107701);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("タマキ", 150, 2, 91002, 46, 8, 40001, 0, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 10, 107901);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("", 150, 0, 91002, 57, 8, 40003, 0, "", 1, 0);
