INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 1, 1, 24001, 321, 2, 40011, 0, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, 125801);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 1, 1, 24001, 322, 2, 40011, 0, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, 126001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 1, 1, 24001, 323, 2, 40011, 0, "んーと。\nこれ、あげる。\nはい", 3, 126101);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("リリ", 1, 2, 24001, 324, 2, 40011, 0, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, 125801);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("クリア", 1, 2, 24001, 325, 2, 40011, 0, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, 126001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("プレシア", 1, 2, 24001, 326, 2, 40011, 0, "お兄。\nきてくれて、うれしい", 6, 126101);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES ("", 100, 0, 91002, 327, 8, 80009, 532001, "", 1, 0);
